  "ground_truth": {
    "basis": "upstream_docs",
    "statement": "Under the PHP-FIG proposed PHPDoc grammar, type-expression = type *(\"|\" type) *(\"&\" type), so a trailing union separator without another type is malformed. PHP itself ignores the comment; the valid array<int, Group> annotation is the control.",
    "runtime_script": "runtime/check.php",
    "citation": "https://github.com/php-fig/fig-standards/blob/master/proposed/phpdoc.md#appendix-a-types"
  },
