        }
      ],
      "allowed": [
        {
          "code": "missingType.iterableValue",
          "line": 5,
          "file": "src/repro.php",
          "reason": "Ignoring the malformed annotation leaves a bare native array parameter without an element type. This is a correct secondary completeness diagnostic."
